  for (const name of used) {
    if (!cost.has(name)) throw fail(`error: unknown task ${name}`);
  }

  const names = Array.from(cost.keys()).sort(cmp);
  const sortedDeps = new Map();
  for (const name of names) sortedDeps.set(name, (deps.get(name) || []).slice().sort(cmp));

