// Iterative DFS reporting the first cycle found, per the specified order.
function checkCycle(graph) {
  const { names, deps } = graph;
  const color = new Map(); // undefined = white, 1 = gray, 2 = black
  const path = [];

  for (const root of names) {
    if (color.get(root) === 2) continue;
