#!/usr/bin/env node

const args = process.argv.slice(2);

// Validate command-line arguments
if (args.length < 1 || args.length > 2) {
  process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n');
  process.exit(2);
}

const mode = args[0];
if (!['waves', 'explain', 'pack'].includes(mode)) {
  process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n');
  process.exit(2);
}

let workerCount = 0;
if (mode === 'pack') {
  if (args.length !== 2) {
    process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n');
    process.exit(2);
  }
  const workerArg = args[1];
  // Validate worker count: must be positive integer, no sign, no leading zero
  if (!/^\d+$/.test(workerArg) || workerArg[0] === '0' || workerArg === '0') {
    process.stderr.write('error: workers must be a positive integer\n');
    process.exit(2);
  }
  workerCount = parseInt(workerArg, 10);
  if (workerCount === 0) {
    process.stderr.write('error: workers must be a positive integer\n');
    process.exit(2);
  }
}

// Read all input
let input = '';
process.stdin.on('data', chunk => {
  input += chunk;
});

process.stdin.on('end', () => {
  try {
    processInput(input, mode, workerCount);
  } catch (error) {
    process.stderr.write(`${error.message}\n`);
    process.exit(error.exitCode || 2);
  }
});

function processInput(input, mode, workerCount) {
  // Split on newlines and drop empty tail
  const lines = input.split('\n');
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop();
  }

  const tasks = new Map();
  const deps = new Map();
  let lineNum = 0;

  // Parse input
  for (let i = 0; i < lines.length; i++) {
    lineNum = i + 1;
    let line = lines[i].trim();

    // Skip empty lines and comments
    if (!line || line.startsWith('#')) {
      continue;
    }

    const parts = line.split(/\s+/);
    const directive = parts[0];

    if (directive === 'task') {
      if (parts.length !== 3) {
        const err = new Error(`error: line ${lineNum}: expected task <name> <cost>`);
        err.exitCode = 2;
        throw err;
      }

      const name = parts[1];
      const costStr = parts[2];

      // Validate task name
      if (!/^[A-Za-z0-9_.\-]+$/.test(name)) {
        const err = new Error(`error: line ${lineNum}: invalid task name ${name}`);
        err.exitCode = 2;
        throw err;
      }

      // Validate cost
      if (!/^\d+$/.test(costStr)) {
        const err = new Error(`error: line ${lineNum}: cost must be a non-negative integer`);
        err.exitCode = 2;
        throw err;
      }

      const cost = parseInt(costStr, 10);

      // Check for duplicate task
      if (tasks.has(name)) {
        const err = new Error(`error: line ${lineNum}: task ${name} is declared twice`);
        err.exitCode = 2;
        throw err;
      }

      tasks.set(name, cost);
      if (!deps.has(name)) {
        deps.set(name, []);
      }
    } else if (directive === 'dep') {
      if (parts.length < 2) {
        const err = new Error(`error: line ${lineNum}: expected dep <name> <dependency>...`);
        err.exitCode = 2;
        throw err;
      }

      const name = parts[1];
      const dependencies = parts.slice(2);

      if (!deps.has(name)) {
        deps.set(name, []);
      }

      const depList = deps.get(name);
      for (const dep of dependencies) {
        if (!depList.includes(dep)) {
          depList.push(dep);
        }
      }
