#!/usr/bin/env node
'use strict';

const NAME_RE = /^[A-Za-z0-9_.-]+$/;
const UINT_RE = /^[0-9]+$/;
const USAGE = 'error: usage: cli.js waves|explain|pack <workers>';

class Fail extends Error {
  constructor(message, code) {
    super(message);
    this.exitCode = code;
  }
}

function fail(message) {
  return new Fail(message, 2);
}

function cmp(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

function maxOf(values) {
  let m = 0;
  for (const v of values) if (v > m) m = v;
  return m;
}

function parseArgs(argv) {
  const mode = argv[0];
  if (mode === 'waves' || mode === 'explain') {
    if (argv.length !== 1) throw fail(USAGE);
    return { mode, workers: 0 };
  }
  if (mode === 'pack') {
    if (argv.length !== 2) throw fail(USAGE);
    const raw = argv[1];
    if (!UINT_RE.test(raw) || raw[0] === '0') {
      throw fail('error: workers must be a positive integer');
    }
    return { mode, workers: Number(raw) };
  }
  throw fail(USAGE);
}

function parseGraph(text) {
  const lines = text.split('\n');
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();

  const cost = new Map(); // name -> cost, declaration order
  const deps = new Map(); // name -> array of unique dependency names
  const depSets = new Map();
  const used = []; // names referenced by dep lines, in input order

  const edgesFor = (name) => {
    if (!deps.has(name)) {
      deps.set(name, []);
      depSets.set(name, new Set());
    }
    return deps.get(name);
  };

  for (let i = 0; i < lines.length; i++) {
    const n = i + 1;
    const line = lines[i].trim();
    if (line === '' || line[0] === '#') continue;
    const parts = line.split(/\s+/);
    const directive = parts[0];

    if (directive === 'task') {
      if (parts.length !== 3) {
        throw fail(`error: line ${n}: expected task <name> <cost>`);
      }
      const name = parts[1];
      if (!NAME_RE.test(name)) {
        throw fail(`error: line ${n}: invalid task name ${name}`);
      }
      if (!UINT_RE.test(parts[2])) {
        throw fail(`error: line ${n}: cost must be a non-negative integer`);
      }
      if (cost.has(name)) {
        throw fail(`error: line ${n}: task ${name} is declared twice`);
      }
      cost.set(name, Number(parts[2]));
      edgesFor(name);
    } else if (directive === 'dep') {
      if (parts.length < 3) {
        throw fail(`error: line ${n}: expected dep <name> <dependency>...`);
      }
      for (let k = 1; k < parts.length; k++) {
        if (!NAME_RE.test(parts[k])) {
          throw fail(`error: line ${n}: invalid task name ${parts[k]}`);
        }
        used.push(parts[k]);
      }
      const name = parts[1];
      const list = edgesFor(name);
      const seen = depSets.get(name);
      for (let k = 2; k < parts.length; k++) {
        const d = parts[k];
        if (!seen.has(d)) {
          seen.add(d);
          list.push(d);
        }
      }
    } else {
      throw fail(`error: line ${n}: unknown directive ${directive}`);
    }
  }

  for (const name of used) {
    if (!cost.has(name)) throw fail(`error: unknown task ${name}`);
  }

  const names = Array.from(cost.keys()).sort(cmp);
  const sortedDeps = new Map();
  for (const name of names) sortedDeps.set(name, (deps.get(name) || []).slice().sort(cmp));

  return { names, cost, deps: sortedDeps };
}

// Iterative DFS reporting the first cycle found, per the specified order.
function checkCycle(graph) {
  const { names, deps } = graph;
  const color = new Map(); // undefined = white, 1 = gray, 2 = black
  const path = [];

  for (const root of names) {
    if (color.get(root) === 2) continue;
    const stack = [{ node: root, i: 0 }];
    color.set(root, 1);
    path.push(root);
    while (stack.length > 0) {
      const frame = stack[stack.length - 1];
      const list = deps.get(frame.node);
      if (frame.i < list.length) {
        const next = list[frame.i++];
        const c = color.get(next);
        if (c === 2) continue;
        if (c === 1) {
          const cycle = path.slice(path.indexOf(next));
          cycle.push(next);
          throw new Fail(`error: cycle: ${cycle.join(' -> ')}`, 3);
        }
        color.set(next, 1);
        path.push(next);
        stack.push({ node: next, i: 0 });
      } else {
        color.set(frame.node, 2);
        path.pop();
        stack.pop();
      }
    }
  }
}

// Dependencies-first ordering; the graph is known to be acyclic here.
function topoOrder(graph) {
  const { names, deps } = graph;
  const indeg = new Map();
  const dependents = new Map();
  for (const name of names) {
    indeg.set(name, deps.get(name).length);
    dependents.set(name, []);
  }
  for (const name of names) {
    for (const d of deps.get(name)) dependents.get(d).push(name);
  }
  const queue = names.filter((n) => indeg.get(n) === 0);
  const order = [];
  for (let i = 0; i < queue.length; i++) {
    const name = queue[i];
    order.push(name);
    for (const dep of dependents.get(name)) {
      const v = indeg.get(dep) - 1;
      indeg.set(dep, v);
      if (v === 0) queue.push(dep);
    }
  }
  return { order, dependents };
}

function analyze(graph) {
  const { names, cost, deps } = graph;
  const { order, dependents } = topoOrder(graph);
  const depth = new Map();
  const start = new Map();
  const finish = new Map();

  for (const name of order) {
    let d = 0;
    let s = 0;
    const list = deps.get(name);
    for (const dep of list) {
      const dd = depth.get(dep) + 1;
      if (dd > d) d = dd;
      const f = finish.get(dep);
      if (f > s) s = f;
    }
    depth.set(name, d);
    start.set(name, s);
    finish.set(name, s + cost.get(name));
  }

  // Priority: cost of the longest chain beginning at the task.
  const priority = new Map();
  for (let i = order.length - 1; i >= 0; i--) {
    const name = order[i];
    let best = 0;
    for (const down of dependents.get(name)) {
      const p = priority.get(down);
      if (p > best) best = p;
    }
    priority.set(name, cost.get(name) + best);
  }

  const total = names.length === 0 ? 0 : maxOf(finish.values());
  return { depth, start, finish, priority, dependents, total };
}

function renderWaves(graph, info) {
  const out = [];
  if (graph.names.length > 0) {
    const maxDepth = maxOf(info.depth.values());
    const waves = [];
    for (let d = 0; d <= maxDepth; d++) waves.push([]);
    for (const name of graph.names) waves[info.depth.get(name)].push(name);
    for (let d = 0; d <= maxDepth; d++) out.push(`wave ${d}: ${waves[d].join(' ')}\n`);
  }
  out.push(`total ${info.total}\n`);
  return out.join('');
}

function renderExplain(graph, info) {
  const out = [];
  for (const name of graph.names) {
    out.push(
      `${name} start=${info.start.get(name)} finish=${info.finish.get(name)} ` +
        `depth=${info.depth.get(name)}\n`
    );
  }
  out.push(`total ${info.total}\n`);
  return out.join('');
}

function renderPack(graph, info, workers) {
  const { names, cost, deps } = graph;
  const { priority } = info;

  const runs = Array.from({ length: workers }, () => []);
  const workerFree = new Array(workers).fill(0);
  const finished = new Map();
  const remainingDeps = new Map();
  for (const name of names) remainingDeps.set(name, deps.get(name).length);

  const pending = new Set(names);
  let time = 0;
  let makespan = 0;

  const readyAt = (name, t) => {
    for (const dep of deps.get(name)) {
      const f = finished.get(dep);
      if (f === undefined || f > t) return false;
    }
    return true;
  };

  while (pending.size > 0) {
    for (;;) {
      let worker = -1;
      for (let i = 0; i < workers; i++) {
        if (workerFree[i] <= time) {
          worker = i;
          break;
        }
      }
      if (worker === -1) break;

      let pick = null;
      for (const name of names) {
        if (!pending.has(name)) continue;
        if (!readyAt(name, time)) continue;
        if (pick === null || priority.get(name) > priority.get(pick)) pick = name;
      }
      if (pick === null) break;

      const s = time;
      const f = s + cost.get(pick);
      pending.delete(pick);
      finished.set(pick, f);
      runs[worker].push(`${pick}@${s}-${f}`);
      workerFree[worker] = f;
      if (f > makespan) makespan = f;
    }

    if (pending.size === 0) break;

    let next = Infinity;
    for (let i = 0; i < workers; i++) {
      if (workerFree[i] > time && workerFree[i] < next) next = workerFree[i];
    }
    for (const name of pending) {
      for (const dep of deps.get(name)) {
        const f = finished.get(dep);
        if (f !== undefined && f > time && f < next) next = f;
      }
    }
    if (next === Infinity) break;
    time = next;
  }

  const out = [];
  for (let i = 0; i < workers; i++) {
    out.push(runs[i].length === 0 ? `worker ${i}:\n` : `worker ${i}: ${runs[i].join(' ')}\n`);
  }
  out.push(`makespan ${names.length === 0 ? 0 : makespan}\n`);
  return out.join('');
}

function run(argv, text) {
  const { mode, workers } = parseArgs(argv);
  const graph = parseGraph(text);
  checkCycle(graph);
  const info = analyze(graph);
  if (mode === 'waves') return renderWaves(graph, info);
  if (mode === 'explain') return renderExplain(graph, info);
  return renderPack(graph, info, workers);
}

function main() {
  const argv = process.argv.slice(2);
  const chunks = [];
  process.stdin.on('data', (c) => chunks.push(c));
  process.stdin.on('end', () => {
    let output;
    try {
      output = run(argv, Buffer.concat(chunks).toString('utf8'));
    } catch (err) {
      if (err instanceof Fail) {
        process.stderr.write(`${err.message}\n`);
        process.exitCode = err.exitCode;
        return;
      }
      throw err;
    }
    process.stdout.write(output);
  });
}

main();

module.exports = { run };

