  if (mode === 'pack') return pack(g, workers);
  if (mode === 'explain') {
    return (
      g.names
        .map((n) => `${n} start=${start.get(n)} finish=${finish.get(n)} depth=${depth.get(n)}\n`)
        .join('') + `total ${total}\n`
    );
  }
  const maxd = g.names.length ? Math.max(...g.names.map((n) => depth.get(n))) : -1;
  let out = '';
  for (let d = 0; d <= maxd; d++)
    out += `wave ${d}: ${g.names.filter((n) => depth.get(n) === d).join(' ')}\n`;
  return out + `total ${total}\n`;
}

let seed = 12345;
const rnd = () => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);
const pool = ['a', 'B', 'c-1', 'd.2', 'e_3', 'F', 'g', 'h9', 'Z', 'a0'];

let bad = 0;
for (let iter = 0; iter < 600; iter++) {
  const n = 1 + Math.floor(rnd() * 9);
  const names = pool.slice(0, n);
  const lines = names.map((x) => `task ${x} ${Math.floor(rnd() * 4)}`);
  for (let i = 1; i < n; i++) {
    const ds = names.slice(0, i).filter(() => rnd() < 0.4);
    if (ds.length) lines.push(`dep ${names[i]} ${ds.join(' ')}`);
  }
  const text = lines.join('\n') + '\n';
  const mode = ['waves', 'explain', 'pack'][iter % 3];
  const workers = 1 + Math.floor(rnd() * 4);
  const argv = mode === 'pack' ? [mode, String(workers)] : [mode];
  const got = spawnSync(process.execPath, [cli, ...argv], { encoding: 'utf8', input: text });
  const want = expected(text, mode, workers);
  if (got.stdout !== want || got.status !== 0) {
    bad++;
    console.log('MISMATCH', argv.join(' '), JSON.stringify(text));
    console.log('got ', JSON.stringify(got.stdout), got.status, got.stderr);
    console.log('want', JSON.stringify(want));
    if (bad > 3) break;
  }
}
console.log(bad === 0 ? 'all match' : `${bad} mismatches`);
"}

