// Naive reference for pack/waves/explain, compared against src/cli.js on random graphs.
import { spawnSync } from 'node:child_process';

const cli = process.argv[2];

function parse(text) {
  const cost = new Map();
  const deps = new Map();
  for (const raw of text.split('\n')) {
    const line = raw.trim();
    if (!line || line[0] === '#') continue;
    const p = line.split(/\s+/);
    if (p[0] === 'task') {
      cost.set(p[1], Number(p[2]));
      if (!deps.has(p[1])) deps.set(p[1], []);
    } else {
      if (!deps.has(p[1])) deps.set(p[1], []);
      for (const d of p.slice(2)) if (!deps.get(p[1]).includes(d)) deps.get(p[1]).push(d);
    }
  }
  const names = [...cost.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  return { names, cost, deps };
}

function times(g) {
  const start = new Map();
  const finish = new Map();
  const depth = new Map();
  const go = (n) => {
    if (finish.has(n)) return;
    let s = 0;
    let d = 0;
    for (const dep of g.deps.get(n)) {
      go(dep);
      s = Math.max(s, finish.get(dep));
      d = Math.max(d, depth.get(dep) + 1);
    }
    start.set(n, s);
    depth.set(n, d);
    finish.set(n, s + g.cost.get(n));
  };
  g.names.forEach(go);
  return { start, finish, depth };
}

function priorities(g) {
  const pr = new Map();
  const go = (n) => {
    if (pr.has(n)) return pr.get(n);
    let best = 0;
    for (const m of g.names) if (g.deps.get(m).includes(n)) best = Math.max(best, go(m));
    pr.set(n, g.cost.get(n) + best);
    return pr.get(n);
  };
  g.names.forEach(go);
  return pr;
}

function pack(g, workers) {
  const pr = priorities(g);
  const runs = Array.from({ length: workers }, () => []);
  const free = new Array(workers).fill(0);
  const fin = new Map();
  const todo = new Set(g.names);
  let t = 0;
  let makespan = 0;
  while (todo.size > 0) {
    for (;;) {
      const w = free.findIndex((f) => f <= t);
      if (w < 0) break;
      let pick = null;
      for (const n of g.names) {
        if (!todo.has(n)) continue;
        if (!g.deps.get(n).every((d) => fin.has(d) && fin.get(d) <= t)) continue;
        if (pick === null || pr.get(n) > pr.get(pick)) pick = n;
      }
      if (pick === null) break;
      const f = t + g.cost.get(pick);
      todo.delete(pick);
      fin.set(pick, f);
      runs[w].push(`${pick}@${t}-${f}`);
      free[w] = f;
      makespan = Math.max(makespan, f);
    }
    if (todo.size === 0) break;
    let next = Infinity;
    for (const f of free) if (f > t) next = Math.min(next, f);
    for (const n of todo)
      for (const d of g.deps.get(n)) {
        const f = fin.get(d);
        if (f !== undefined && f > t) next = Math.min(next, f);
      }
    if (next === Infinity) break;
    t = next;
  }
  return (
    runs.map((r, i) => (r.length ? `worker ${i}: ${r.join(' ')}\n` : `worker ${i}:\n`)).join('') +
    `makespan ${g.names.length === 0 ? 0 : makespan}\n`
  );
}

function expected(text, mode, workers) {
  const g = parse(text);
  const { start, finish, depth } = times(g);
  const total = g.names.length === 0 ? 0 : Math.max(...g.names.map((n) => finish.get(n)));
  if (mode === 'pack') return pack(g, workers);
  if (mode === 'explain') {
    return (
      g.names
        .map((n) => `${n} start=${start.get(n)} finish=${finish.get(n)} depth=${depth.get(n)}\n`)
        .join('') + `total ${total}\n`
    );
  }
  const maxd = g.names.length ? Math.max(...g.names.map((n) => depth.get(n))) : -1;
  let out = '';
  for (let d = 0; d <= maxd; d++)
    out += `wave ${d}: ${g.names.filter((n) => depth.get(n) === d).join(' ')}\n`;
  return out + `total ${total}\n`;
}

let seed = 12345;
const rnd = () => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);
const pool = ['a', 'B', 'c-1', 'd.2', 'e_3', 'F', 'g', 'h9', 'Z', 'a0'];

let bad = 0;
for (let iter = 0; iter < 600; iter++) {
  const n = 1 + Math.floor(rnd() * 9);
  const names = pool.slice(0, n);
  const lines = names.map((x) => `task ${x} ${Math.floor(rnd() * 4)}`);
  for (let i = 1; i < n; i++) {
    const ds = names.slice(0, i).filter(() => rnd() < 0.4);
    if (ds.length) lines.push(`dep ${names[i]} ${ds.join(' ')}`);
  }
  const text = lines.join('\n') + '\n';
  const mode = ['waves', 'explain', 'pack'][iter % 3];
  const workers = 1 + Math.floor(rnd() * 4);
  const argv = mode === 'pack' ? [mode, String(workers)] : [mode];
  const got = spawnSync(process.execPath, [cli, ...argv], { encoding: 'utf8', input: text });
  const want = expected(text, mode, workers);
  if (got.stdout !== want || got.status !== 0) {
    bad++;
    console.log('MISMATCH', argv.join(' '), JSON.stringify(text));
    console.log('got ', JSON.stringify(got.stdout), got.status, got.stderr);
    console.log('want', JSON.stringify(want));
    if (bad > 3) break;
  }
}
console.log(bad === 0 ? 'all match' : `${bad} mismatches`);
